function readTitle(){const feature=document.querySelector('#feature-card .fact-place-name')?.textContent?.trim(),heading=document.querySelector('#detail-name')?.textContent?.trim(),village=document.querySelector('#crumb-village')?.textContent?.trim(),place=feature||heading||village;return place?`${REGION.title} · ${place}`:REGION.title;}
