  const title=readTitle();ctx.fillStyle='#28231f';ctx.font=`${Math.round(18*scale)}px Georgia,serif`;ctx.textBaseline='middle';ctx.textAlign='start';const titleMax=output.width-40*scale;let titleText=title;while(ctx.measureText(titleText).width>titleMax&&titleText.length>3)titleText=`${titleText.slice(0,-4)}…`;ctx.fillText(titleText,20*scale,top*.48);ctx.fillStyle='#766e65';ctx.font=`${Math.round(9*scale)}px system-ui,sans-serif`;const mode=renderer.mode==='atlas'?'atlas':'aerial';const exag=Number(renderer.exaggeration)||1;const opacity=Math.round((Number(renderer.aocOpacity)||0)*100);ctx.fillText(`Current view · ${mode} · terrain ${exag}× · ${legendEnabled?`AOC fill ${opacity}%`:'AOC hidden'}`,20*scale,top*.78);
